// Package width computes the number of terminal cells a string occupies.
//
// The rules follow UAX #11 (East Asian Width) for individual code points and
// UAX #29 extended grapheme clusters for sequences: every grapheme cluster
// takes the width of its first code point that has a non-zero width.
package width

import (
	"os"
	"regexp"
	"strings"
)

type interval struct {
	first rune
	last  rune
}

type table []interval

func (t table) contains(r rune) bool {
	if len(t) == 0 || r < t[0].first || r > t[len(t)-1].last {
		return false
	}
	lo, hi := 0, len(t)-1
	for lo <= hi {
		mid := (lo + hi) / 2
		switch {
		case t[mid].last < r:
			lo = mid + 1
		case t[mid].first > r:
			hi = mid - 1
		default:
			return true
		}
	}
	return false
}

// Code points that never occupy a cell.
var nonprint = table{
	{0x0000, 0x001F}, {0x007F, 0x009F}, {0x00AD, 0x00AD},
	{0x070F, 0x070F}, {0x180B, 0x180E}, {0x200B, 0x200F},
	{0x2028, 0x202E}, {0x206A, 0x206F}, {0xD800, 0xDFFF},
	{0xFEFF, 0xFEFF}, {0xFFF9, 0xFFFB}, {0xFFFE, 0xFFFF},
}

// Private use areas are treated as ambiguous.
var private = table{
	{0x00E000, 0x00F8FF}, {0x0F0000, 0x0FFFFD}, {0x100000, 0x10FFFD},
}

// EastAsian reports whether ambiguous characters are treated as wide.
var EastAsian = detectEastAsian()

func detectEastAsian() bool {
	env := os.Getenv("RUNEWIDTH_EASTASIAN")
	if env != "" {
		return env == "1"
	}
	return localeIsEastAsian()
}

var localeRe = regexp.MustCompile(`^[a-z][a-z][a-z]?(?:_[A-Z][A-Z])?\.(.+)`)

var multibyteCharsets = map[string]int{
	"utf-8":   6,
	"utf8":    6,
	"jis":     8,
	"eucjp":   3,
	"euckr":   2,
	"euccn":   2,
	"sjis":    2,
	"cp932":   2,
	"cp51932": 2,
	"cp936":   2,
	"cp949":   2,
	"cp950":   2,
	"big5":    2,
	"gbk":     2,
	"gb2312":  2,
}

func localeIsEastAsian() bool {
	locale := os.Getenv("LC_ALL")
	if locale == "" {
		locale = os.Getenv("LC_CTYPE")
	}
	if locale == "" {
		locale = os.Getenv("LANG")
	}
	if locale == "POSIX" || locale == "C" {
		return false
	}
	if len(locale) > 1 && locale[0] == 'C' && (locale[1] == '.' || locale[1] == '-') {
		return false
	}
	return charsetIsEastAsian(locale)
}

func charsetIsEastAsian(locale string) bool {
	charset := strings.ToLower(locale)
	if m := localeRe.FindStringSubmatch(locale); len(m) == 2 {
		charset = strings.ToLower(m[1])
	}
	if strings.HasSuffix(charset, "@cjk_narrow") {
		return false
	}
	if i := strings.IndexByte(charset, '@'); i >= 0 {
		charset = charset[:i]
	}
	n, ok := multibyteCharsets[charset]
	if !ok || n <= 1 {
		return false
	}
	if charset[0] != 'u' {
		return true
	}
	return strings.HasPrefix(locale, "ja") ||
		strings.HasPrefix(locale, "ko") ||
		strings.HasPrefix(locale, "zh")
}

// Rune returns the number of cells used by a single code point.
func Rune(r rune) int {
	if r < 0 || r > 0x10FFFF {
		return 0
	}
	if nonprint.contains(r) || combining.contains(r) {
		return 0
	}
	if EastAsian && (private.contains(r) || ambiguous.contains(r)) {
		return 2
	}
	if doublewidth.contains(r) {
		return 2
	}
	return 1
}

// String returns the number of cells used by s.
func String(s string) int {
	total := 0
	seg := newSegmenter(s)
	for {
		cluster, ok := seg.next()
		if !ok {
			break
		}
		w := 0
		for _, r := range cluster {
			if w = Rune(r); w > 0 {
				break
			}
		}
		total += w
	}
	return total
}
EOF"}

