	gpSpacingMark
	gpL
	gpV
	gpT
	gpLV
	gpLVT
	gpExtPict
)

type propRange struct {
	first rune
	last  rune
	prop  uint8
}

func graphemeProp(r rune) uint8 {
	lo, hi := 0, len(graphemeProps)-1
	for lo <= hi {
		mid := (lo + hi) / 2
		p := &graphemeProps[mid]
		switch {
		case p.last < r:
			lo = mid + 1
		case p.first > r:
			hi = mid - 1
		default:
			return p.prop
		}
	}
	return gpOther
}

// segmenter splits a string into extended grapheme clusters (UAX #29).
type segmenter struct {
	s   string
	pos int
}

func newSegmenter(s string) *segmenter {
	return &segmenter{s: s}
}

// next returns the runes of the next grapheme cluster.
func (g *segmenter) next() ([]rune, bool) {
	if g.pos >= len(g.s) {
		return nil, false
	}
	var out []rune

	r, size := utf8.DecodeRuneInString(g.s[g.pos:])
	g.pos += size
	out = append(out, r)

	prev := graphemeProp(r)
	riCount := 0
	if prev == gpRI {
		riCount = 1
	}
	// pict: 0 = nothing, 1 = ExtPict Extend*, 2 = ExtPict Extend* ZWJ
	pict := 0
	if prev == gpExtPict {
		pict = 1
	}

	for g.pos < len(g.s) {
		r, size = utf8.DecodeRuneInString(g.s[g.pos:])
		cur := graphemeProp(r)
		if isBoundary(prev, cur, riCount, pict) {
			break
		}
		g.pos += size
		out = append(out, r)

		if cur == gpRI {
			riCount++
		} else {
			riCount = 0
		}
		switch {
		case cur == gpExtPict:
			pict = 1
		case cur == gpExtend && pict == 1:
			pict = 1
		case cur == gpZWJ && pict == 1:
			pict = 2
		default:
			pict = 0
		}
		prev = cur
	}
	return out, true
}

func isBoundary(prev, cur uint8, riCount, pict int) bool {
	switch {
	case prev == gpCR && cur == gpLF: // GB3
		return false
	case prev == gpControl || prev == gpCR || prev == gpLF: // GB4
		return true
	case cur == gpControl || cur == gpCR || cur == gpLF: // GB5
		return true
	case prev == gpL && (cur == gpL || cur == gpV || cur == gpLV || cur == gpLVT): // GB6
		return false
	case (prev == gpLV || prev == gpV) && (cur == gpV || cur == gpT): // GB7
		return false
	case (prev == gpLVT || prev == gpT) && cur == gpT: // GB8
		return false
	case cur == gpExtend || cur == gpZWJ: // GB9
		return false
	case cur == gpSpacingMark: // GB9a
		return false
	case prev == gpPrepend: // GB9b
		return false
	case prev == gpZWJ && cur == gpExtPict && pict == 2: // GB11
		return false
	case prev == gpRI && cur == gpRI && riCount%2 == 1: // GB12, GB13
		return false
	}
	return true // GB999
}
