}

// DefaultStyle draws a box around the table.
var DefaultStyle = Style{TopBorder: true, BottomBorder: true, Corner: "+", Horizontal: "-", Vertical: "|"}

// MarkdownStyle renders a Markdown compatible table.
var MarkdownStyle = Style{TopBorder: false, BottomBorder: false, Corner: "|", Horizontal: "-", Vertical: "|"}

// Table accumulates a header and rows and writes them on Render.
type Table struct {
	out     io.Writer
	style   Style
	header  [][]string
	rows    [][][]string
	widths  map[int]int
	heights map[int]int
}

// New returns an empty table writing to out.
func New(out io.Writer, style Style) *Table {
	return &Table{
		out:     out,
		style:   style,
		widths:  map[int]int{},
		heights: map[int]int{},
	}
}

// SetHeader sets the column titles.
func (t *Table) SetHeader(titles []string) {
	t.header = nil
	for i, h := range titles {
		t.header = append(t.header, t.layoutCell(h, i, headerRowKey))
	}
}

// Append adds a row.
func (t *Table) Append(cells []string) {
	rowKey := len(t.rows)
	var row [][]string
	for i, c := range cells {
		row = append(row, t.layoutCell(c, i, rowKey))
	}
	t.rows = append(t.rows, row)
}

// Render writes the whole table.
func (t *Table) Render() {
	if t.style.TopBorder {
		t.separator()
	}
	t.renderHeader()
	for i, row := range t.rows {
		t.renderRow(row, i)
	}
	if t.style.BottomBorder {
		t.separator()
	}
}

// DisplayWidth is the visible width of s, ignoring simple ANSI color codes.
func DisplayWidth(s string) int {
	return width.String(ansiRe.ReplaceAllLiteralString(s, ""))
}

// layoutCell splits a cell into lines and records the column width and
// row height it needs.
func (t *Table) layoutCell(text string, col, rowKey int) []string {
	paragraphs := strings.Split(text, "\n")
	limit := 0
	for _, p := range paragraphs {
		if w := DisplayWidth(p); w > limit {
			limit = w
		}
	}
	if limit > maxColWidth {
		limit = maxColWidth
	}
	need := limit
	lines := wrapText(strings.Join(paragraphs, " "), limit)
	for _, l := range lines {
		if w := DisplayWidth(l); w > need {
			need = w
		}
	}

	if cur, ok := t.widths[col]; !ok || cur < need || cur == 0 {
		t.widths[col] = need
	}
	if cur, ok := t.heights[rowKey]; !ok || cur < len(lines) || cur == 0 {
		t.heights[rowKey] = len(lines)
	}
	return lines
}

// wrapText breaks s into lines of at most limit cells, minimising the sum of
// squared trailing gaps. Words longer than the limit widen it.
func wrapText(s string, limit int) []string {
	words := strings.Split(strings.ReplaceAll(s, "\n", " "), " ")
	for _, w := range words {
		if dw := DisplayWidth(w); dw > limit {
			limit = dw
		}
	}

	n := len(words)
	wordWidth := make([]int, n)
	for i, w := range words {
		wordWidth[i] = width.String(w)
	}
	// span(i, j) = width of words[i..j] joined by single spaces
	prefix := make([]int, n+1)
	for i := 0; i < n; i++ {
		prefix[i+1] = prefix[i] + wordWidth[i]
	}
	span := func(i, j int) int {
		return prefix[j+1] - prefix[i] + (j - i)
	}

	cost := make([]int, n)
	brk := make([]int, n)
	for i := range cost {
		cost[i] = math.MaxInt32
	}
	for i := n - 1; i >= 0; i-- {
		if span(i, n-1) <= limit {
			cost[i] = 0
			brk[i] = n
			continue
		}
		for j := i + 1; j < n; j++ {
			l := span(i, j-1)
			gap := limit - l
			c := gap*gap + cost[j]
			if l > limit {
				c += wrapPenalty
			}
			if c < cost[i] {
				cost[i] = c
				brk[i] = j
			}
		}
	}

	var lines []string
	for i := 0; i < n; i = brk[i] {
		lines = append(lines, strings.Join(words[i:brk[i]], " "))
	}
	return lines
}

func (t *Table) separator() {
	var b strings.Builder
	b.WriteString(t.style.Corner)
	for i := 0; i < len(t.widths); i++ {
		b.WriteString(t.style.Horizontal)
		b.WriteString(strings.Repeat(t.style.Horizontal, t.widths[i]))
		b.WriteString(t.style.Horizontal)
		b.WriteString(t.style.Corner)
	}
	b.WriteString("\n")
	io.WriteString(t.out, b.String())
}

func (t *Table) renderHeader() {
	if len(t.header) == 0 {
		return
	}
	cols := len(t.widths)
	for x := 0; x < t.heights[headerRowKey]; x++ {
		var b strings.Builder
		b.WriteString(t.style.Vertical)
		for y := 0; y < cols; y++ {
			h := ""
			if y < len(t.header) && x < len(t.header[y]) {
				h = t.header[y][x]
			}
			b.WriteString(" ")
			b.WriteString(center(h, t.widths[y]))
			b.WriteString(" ")
			b.WriteString(t.style.Vertical)
		}
		b.WriteString("\n")
		io.WriteString(t.out, b.String())
	}
	t.separator()
}

func (t *Table) renderRow(row [][]string, rowKey int) {
	height := t.heights[rowKey]
	for i := range row {
		for len(row[i]) < height {
			row[i] = append(row[i], "  ")
		}
	}
	for x := 0; x < height; x++ {
		var b strings.Builder
		for y := range row {
			b.WriteString(t.style.Vertical)
			b.WriteString(" ")
			s := row[y][x]
			if numericRe.MatchString(strings.TrimSpace(s)) {
				b.WriteString(padLeft(s, t.widths[y]))
			} else {
				b.WriteString(padRight(s, t.widths[y]))
			}
			b.WriteString(" ")
		}
		b.WriteString(t.style.Vertical)
		b.WriteString("\n")
		io.WriteString(t.out, b.String())
	}
}

func center(s string, w int) string {
	gap := w - DisplayWidth(s)
	if gap <= 0 {
		return s
	}
	left := gap / 2
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", gap-left)
}

func padRight(s string, w int) string {
	gap := w - DisplayWidth(s)
	if gap <= 0 {
		return s
	}
	return s + strings.Repeat(" ", gap)
}

func padLeft(s string, w int) string {
	gap := w - DisplayWidth(s)
	if gap <= 0 {
		return s
	}
	return strings.Repeat(" ", gap) + s
}
