// Package mod describes the modules reported by `go list -m -json`.
package mod

import "time"

// Module is a single entry of `go list -u -m -json all`.
type Module struct {
	Path      string
	Version   string
	Versions  []string
	Replace   *Module
	Time      *time.Time
	Update    *Module
	Main      bool
	Indirect  bool
	Dir       string
	GoMod     string
	GoVersion string
	Error     *ModuleError
}

// ModuleError is the error reported for a module that could not be loaded.
type ModuleError struct {
	Err string
}

// effective returns the module that is actually used: the replacement when
// there is one, the module itself otherwise.
func (m *Module) effective() *Module {
	if m.Replace != nil {
		return m.Replace
	}
	return m
}

// InvalidTimestamp reports whether the proposed update is older than the
// version currently in use.
func (m *Module) InvalidTimestamp() bool {
	cur := m.effective()
	if cur.Time == nil || cur.Update == nil {
		return false
	}
	return cur.Time.After(*cur.Update.Time)
}

// CurrentVersion is the version in use, taking replacements into account.
func (m *Module) CurrentVersion() string {
	return m.effective().Version
}

// HasUpdate reports whether a newer version of the module in use exists.
func (m *Module) HasUpdate() bool {
	return m.effective().Update != nil
}

// NewVersion is the version the module in use can be updated to, if any.
func (m *Module) NewVersion() string {
	cur := m.effective()
	if cur.Update == nil {
		return ""
	}
	return cur.Update.Version
}
