// Package runner implements the go-mod-outdated command.
package runner

import (
	"encoding/json"
	"errors"
	"io"
	"os"
	"strconv"

	"github.com/psampaz/go-mod-outdated/internal/mod"
	"github.com/psampaz/go-mod-outdated/internal/table"
)

var tableHeader = []string{"MODULE", "VERSION", "NEW VERSION", "DIRECT", "VALID TIMESTAMPS"}

// Run reads the JSON stream produced by `go list -u -m -json all` from in and
// writes a table describing the modules to out.
//
// update keeps only the modules that have an update, direct keeps only the
// direct dependencies. When exitWithNonZero is set, the process exits with
// status 1 if at least one of the listed modules is outdated.
func Run(in io.Reader, out io.Writer, update, direct, exitWithNonZero bool, style string) error {
	modules, err := readModules(in)
	if err != nil {
		return err
	}

	modules = filterModules(modules, update, direct)

	if len(modules) == 0 {
		return nil
	}

	// The table is only rendered once every module has been decoded and
	// filtered, so a decoding error never produces partial output.
	//
	// Rows keep the order in which `go list` reported the modules.
	//
	// Afterwards the CI check is performed on the very same rows.
	renderTable(out, modules, style)

	if exitWithNonZero && hasOutdated(modules) {
		os.Exit(1)
	}

	return nil
}

func readModules(in io.Reader) ([]mod.Module, error) {
	var modules []mod.Module
	dec := json.NewDecoder(in)
	for {
		var m mod.Module
		err := dec.Decode(&m)
		if errors.Is(err, io.EOF) {
			return modules, nil
		}
		if err != nil {
			return nil, err
		}
		modules = append(modules, m)
	}
}

func filterModules(modules []mod.Module, update, direct bool) []mod.Module {
	var out []mod.Module
	for _, m := range modules {
		if m.Main {
			continue
		}
		if update && m.Update == nil {
			continue
		}
		if direct && m.Indirect {
			continue
		}
		out = append(out, m)
	}
	return out
}

func renderTable(out io.Writer, modules []mod.Module, style string) {
	t := table.New(out, tableStyle(style))
	t.SetHeader(tableHeader)
	for i := range modules {
		m := &modules[i]
		valid := !m.InvalidTimestamp()
		t.Append([]string{
			m.Path,
			m.CurrentVersion(),
			m.NewVersion(),
			strconv.FormatBool(!m.Indirect),
			strconv.FormatBool(valid),
		})
	}
	t.Render()
}

func tableStyle(style string) table.Style {
	if style == "markdown" {
		return table.MarkdownStyle
	}
	return table.DefaultStyle
}

func hasOutdated(modules []mod.Module) bool {
	for i := range modules {
		if modules[i].HasUpdate() {
			return true
		}
	}
	return false
}
EOF
